import SwiftUI
struct RootTabView:View{@EnvironmentObject var session:SessionStore;@State private var quickMenu=false;@State private var entryType:TransactionType?
 var body:some View{ZStack(alignment:.bottom){TabView{DashboardView(model:DashboardViewModel(container:session.container)).tabItem{Label("Ana Sayfa",systemImage:"house")};AccountsView().tabItem{Label("Hesaplar",systemImage:"wallet.bifold")};Color.clear.tabItem{Label("",systemImage:"plus")};UpcomingView().tabItem{Label("Yaklaşan",systemImage:"calendar")};ReportsView().tabItem{Label("Raporlar",systemImage:"chart.bar")}};Button{quickMenu=true}label:{Image(systemName:"plus").font(.title2.bold()).foregroundStyle(.white).frame(width:58,height:58).background(Color.accentColor,in:Circle()).shadow(radius:5)}.padding(.bottom,4)}.confirmationDialog("Hızlı İşlem",isPresented:$quickMenu,titleVisibility:.visible){Button("Gelir"){entryType = .income};Button("Gider"){entryType = .expense};Button("Transfer"){entryType = .transfer};Button("Tahsilat"){entryType = .collection};Button("Ödeme"){entryType = .payment}}.sheet(item:$entryType){type in if let book=session.selectedBook{TransactionEntryView(model:TransactionEntryViewModel(type:type,book:book,container:session.container))}else{ContentUnavailableView("Önce defter seçin",systemImage:"book")}}}
}
extension TransactionType:Identifiable{var id:String{rawValue}}
